const { json: _dropJsonKey, ...safe } = $json;

function isValidPublicMp4(url) {
  const value = String(url || "").trim();
  if (!value || !/^https:\/\//i.test(value)) return false;
  let parsed;
  try { parsed = new URL(value); } catch (e) { return false; }
  const host = String(parsed.hostname || "").toLowerCase();
  if (!host || host === "example.com" || host.endsWith(".example.com")) return false;
  if (/^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[0-1])\.)/.test(host)) return false;
  return /\.mp4($|\?)/i.test(parsed.pathname + parsed.search);
}

const videoUrl = String(safe.video_url || "").trim();
if (!isValidPublicMp4(videoUrl)) {
  return [];
}

return {
  json: {
    ...safe,
    video_url: videoUrl,
    caption:
      `[${safe.title}]\n\n` +
      `${safe.body}\n\n` +
      `?? ??:\n${safe.subtitles}\n\n` +
      `?? ??:\n${safe.source_url}\n\n` +
      `${safe.hashtags}`,
    reply_markup: JSON.stringify({
      inline_keyboard: [
        [
          { text: '? Approve', callback_data: `approve|${safe.content_key}` },
          { text: '?? Regen Text', callback_data: `regen_contents|${safe.content_key}` }
        ],
        [
          { text: '?? Regen Video', callback_data: `regen_reel|${safe.content_key}` },
          { text: '? Delete', callback_data: `delete|${safe.content_key}` }
        ]
      ]
    })
  }
};
